import{_ as o,C as a,o as t,c as n,E as i,a2 as s}from"./chunks/framework.vOTwFLKw.js";const q=JSON.parse('{"title":"Free Online Image Cropper and Resizer","description":"Crop and resize PNG, JPEG, and WebP images online for free. Create square, round, squircle, or rounded app icon artwork at an exact output resolution.","frontmatter":{"title":"Free Online Image Cropper and Resizer","description":"Crop and resize PNG, JPEG, and WebP images online for free. Create square, round, squircle, or rounded app icon artwork at an exact output resolution.","pageClass":"crop-tool-layout","permalink":"/cropimage/","canonicalUrl":"https://curvednebula.com/cropimage/","meta":[{"name":"keywords","content":"image cropper, image resizer, crop image online, resize image online, crop and resize image, photo cropper, photo resizer, PNG resizer, JPEG resizer, WebP resizer, app icon creator, app icon cropper, app icon maker, crop image for app icon, squircle app icon, round app icon, rounded corner app icon, transparent PNG icon"},{"property":"og:title","content":"Free Online Image Cropper and Resizer"},{"property":"og:description","content":"Crop and resize images or prepare square, round, squircle, and rounded app icon artwork at an exact resolution in your browser."},{"property":"og:type","content":"website"},{"property":"og:url","content":"https://curvednebula.com/cropimage/"},{"name":"twitter:card","content":"summary"},{"name":"twitter:title","content":"Free Online Image Cropper and Resizer"},{"name":"twitter:description","content":"Crop and resize images to exact dimensions online. Free, private, and browser-based."}],"aside":false},"headers":[],"relativePath":"cropimage/index.md","filePath":"cropimage/index.md"}'),p={name:"cropimage/index.md"};function c(d,e,l,u,h,m){const r=a("ImageCrop");return t(),n("div",null,[i(r),e[0]||(e[0]=s('<h1 id="crop-and-resize-images-online" tabindex="-1">Crop and Resize Images Online <a class="header-anchor" href="#crop-and-resize-images-online" aria-label="Permalink to &quot;Crop and Resize Images Online&quot;">​</a></h1><p>Crop and resize a photo or image to the exact size you need. Choose square corners, a round or squircle crop, or rounded corners with a custom radius. Optionally set new output dimensions, then save the result as PNG, JPEG, or WebP. Round, squircle, and rounded-corner crops are saved as transparent PNGs. Everything happens locally in your browser—your image is never uploaded.</p><p>The cropper can also prepare artwork for app icons, website icons, avatars, and profile images. Use a square crop for a conventional icon, squircle for a smooth app-icon silhouette, round for circular icons, or rounded corners with a custom radius. Enable <strong>Resize output</strong> to create the exact pixel dimensions you need, then export a transparent PNG for shaped icons.</p><h2 id="howto" tabindex="-1">Howto <a class="header-anchor" href="#howto" aria-label="Permalink to &quot;Howto&quot;">​</a></h2><ol><li>Select an image from your device or drag and drop it into the cropper.</li><li>Drag inside the crop area to reposition it.</li><li>Resize the selection with the corner or edge handles.</li><li>Choose square corners, round, squircle, or rounded corners crop. Rounded corners default to 20% of the cropped image&#39;s shortest side, or you can enter a custom radius in output pixels.</li><li>Choose an aspect ratio or enter exact pixel values if needed. Round and squircle crops use a locked 1:1 ratio.</li><li>To resize the cropped result, enable <strong>Resize output</strong> and enter its width or height. Keep the aspect ratio locked to avoid distortion.</li><li>Select PNG, JPEG, or WebP and save the cropped image. Round, squircle, and rounded-corner crops automatically use PNG so the corners stay transparent.</li></ol><h2 id="frequently-asked-questions" tabindex="-1">Frequently asked questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently asked questions&quot;">​</a></h2><h3 id="does-cropping-reduce-image-quality" tabindex="-1">Does cropping reduce image quality? <a class="header-anchor" href="#does-cropping-reduce-image-quality" aria-label="Permalink to &quot;Does cropping reduce image quality?&quot;">​</a></h3><p>Cropping removes pixels outside the selected area. Resizing is optional; reducing the output dimensions usually preserves more visible detail than enlarging them. PNG export is lossless, while JPEG and WebP use the quality level you select.</p><h3 id="can-i-crop-an-image-to-exact-pixel-dimensions" tabindex="-1">Can I crop an image to exact pixel dimensions? <a class="header-anchor" href="#can-i-crop-an-image-to-exact-pixel-dimensions" aria-label="Permalink to &quot;Can I crop an image to exact pixel dimensions?&quot;">​</a></h3><p>Yes. Enter the X and Y position plus the width and height in the crop area controls. To make the saved image a different exact size, enable <strong>Resize output</strong> and enter the output width and height. The final size is shown before you save.</p><h3 id="can-i-resize-an-image-without-cropping-it" tabindex="-1">Can I resize an image without cropping it? <a class="header-anchor" href="#can-i-resize-an-image-without-cropping-it" aria-label="Permalink to &quot;Can I resize an image without cropping it?&quot;">​</a></h3><p>Yes. Leave the crop area expanded to the full image, enable <strong>Resize output</strong>, and enter the new width or height. Keep the aspect ratio locked to resize without distortion.</p><h3 id="can-i-crop-transparent-images" tabindex="-1">Can I crop transparent images? <a class="header-anchor" href="#can-i-crop-transparent-images" aria-label="Permalink to &quot;Can I crop transparent images?&quot;">​</a></h3><p>Yes. Choose PNG or WebP to preserve transparency. JPEG does not support transparency, so transparent areas are filled with white.</p>',14))])}const f=o(p,[["render",c]]);export{q as __pageData,f as default};
